using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Newtonsoft.Json.Linq;
public static class ExportObstacleHeights {
 const string Repo="G:/new_project/holdem-mount-stream-20261108";
 public static object Run(){var zones=JArray.Parse(File.ReadAllText(Repo+"/src/lib/generated/mount-sunday-zones.json"));int matched=0;foreach(JObject z in zones){int id=(int)z["id"];var scene=EditorSceneManager.OpenScene("Assets/Island/MountRuntime/Scenes/MountZone"+(id+1).ToString("00")+".unity",OpenSceneMode.Additive);try{var ts=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Transform>(true)).Where(t=>t.name.StartsWith("tree")||t.name.StartsWith("rock")).ToArray();foreach(JObject o in z["obstacles"]){float x=(float)o["x"]/100,y=((float)o["y"]-5000)/100;var t=ts.OrderBy(v=>Vector2.Distance(new Vector2(v.position.x,v.position.z),new Vector2(x,y))).FirstOrDefault();if(!t||Vector2.Distance(new Vector2(t.position.x,t.position.z),new Vector2(x,y))>.1f)throw new Exception("No obstacle match zone "+id);var rs=t.GetComponentsInChildren<Renderer>(true);if(rs.Length==0)throw new Exception("No bounds");var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);o["baseElevation"]=b.min.y*100;o["height"]=b.size.y*100;o["source"]=t.name;matched++;}}finally{EditorSceneManager.CloseScene(scene,true);}}File.WriteAllText(Repo+"/src/lib/generated/mount-sunday-zones.json",zones.ToString(Newtonsoft.Json.Formatting.None));return new{matched};}
}
